import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const f=JSON.parse('{"title":"Sources","description":"","frontmatter":{"title":"Sources"},"headers":[],"relativePath":"docs/concepts/sources.md","filePath":"docs/concepts/sources.md","lastUpdated":1794508483000}'),r={name:"docs/concepts/sources.md"};function n(i,e,c,d,l,u){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h1><p>A <strong>source</strong> is a file (or set of files) that feeds data into a project — a bank statement, a brokerage statement, a spreadsheet export, or a general document. A project can have as many sources as you like; the <a href="/docs/getting-started/add-first-source">Add your first source</a> page covers adding one.</p><h2 id="managing-sources" tabindex="-1">Managing sources <a class="header-anchor" href="#managing-sources" aria-label="Permalink to &quot;Managing sources&quot;">​</a></h2><p>The Sources view for a project lists everything that&#39;s been added, with a few actions available on each:</p><ul><li><strong>Relocate</strong>, where offered — point a source at a new location if the app still needs its original file. Imported financial statements normally have an encrypted local copy.</li><li><strong>Rescan</strong> — re-run parsing on the existing file in place, useful after a parser has been fixed or improved.</li><li><strong>Remove</strong> — take a source (and its data) out of the project.</li></ul><h2 id="when-a-format-isn-t-recognized" tabindex="-1">When a format isn&#39;t recognized <a class="header-anchor" href="#when-a-format-isn-t-recognized" aria-label="Permalink to &quot;When a format isn&#39;t recognized&quot;">​</a></h2><p>Review the import result when a file is not recognized. Being listed as a source does not mean financial records were extracted. General Documents can be used for document questions; structured financial analysis needs a supported format. To request support or a parser fix, see <a href="/docs/tools/add-new-institution">Add New Institution</a>.</p>',7)])])}const h=a(r,[["render",n]]);export{f as __pageData,h as default};
